5: export function chosenOrder(value) {
6:   const choices = Object.freeze({
7:     recent: 'created_at DESC',
8:     amount: 'total_cents DESC',
9:     name: 'customer_id ASC'
10:   });
11:   return Object.hasOwn(choices, value) ? choices[value] : choices.recent;
12: }

